// db.query({ after, take }) -> Promise<row[]>   at most `take` rows, newest first, after the position `after`
// db.count()                -> Promise<number>  full scan
export async function listPage(db, params) {
  // TODO: clamp the limit (default 20, 1..100); return { items, hasMore, next } with one query and no count
}

drills.solution:
const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const pageSize = (limit) => {
  const n = typeof limit === 'string' && /^-?\d+$/.test(limit) ? Number(limit) : limit;
  if (!Number.isInteger(n)) return DEFAULT_LIMIT;
  return Math.min(MAX_LIMIT, Math.max(1, n));
};

export async function listPage(db, params) {
  const size = pageSize(params.limit);
  const rows = await db.query({ after: params.after ?? null, take: size + 1 });
  const hasMore = rows.length > size;
  const items = hasMore ? rows.slice(0, size) : rows;
  const last = items[items.length - 1];
  return { items, hasMore, next: hasMore ? { createdAt: last.createdAt, id: last.id } : null };
}

